#include <vector>
#include <unordered_map>

class Solution {
public:
    int firstUniqueFrequency(std::vector<int>& nums) {
        std::unordered_map<int, int> freq;
        for (int x : nums) freq[x]++;
        std::unordered_map<int, int> freqCount;
        for (const auto& [k, v] : freq) freqCount[v]++;
        for (int x : nums) {
            if (freqCount[freq[x]] == 1) return x;
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int firstUniqueFrequency(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.put(x, freq.getOrDefault(x, 0) + 1);
        Map<Integer, Integer> freqCount = new HashMap<>();
        for (int count : freq.values()) freqCount.put(count, freqCount.getOrDefault(count, 0) + 1);
        for (int x : nums) {
            if (freqCount.get(freq.get(x)) == 1) return x;
        }
        return -1;
    }
}

